import { TransformDecodeCheckError, TransformDecodeError, Value } from "@sinclair/typebox/value";
import { envSchema, envValidator, pluginSettingsSchema, permitRequestValidator } from "../types";
export function validateAndDecodeSchemas(rawEnv, rawSettings) {
    const errors = [];
    const env = Value.Default(envSchema, rawEnv);
    if (!envValidator.test(env)) {
        for (const error of envValidator.errors(env)) {
            console.error(error);
            errors.push(error);
        }
    }
    const settings = Value.Default(pluginSettingsSchema, rawSettings);
    if (!settings.evmPrivateEncrypted) {
        errors.push({
            message: "evmPrivateEncrypted is required",
            path: "/evmPrivateEncrypted",
            schema: pluginSettingsSchema,
            type: 0,
            value: settings.evmPrivateEncrypted,
        });
    }
    const permits = settings.permitRequests;
    for (const permit of permits) {
        if (!permitRequestValidator.test(permit)) {
            for (const error of permitRequestValidator.errors(permit)) {
                errors.push(error);
            }
        }
    }
    if (errors.length) {
        throw { errors };
    }
    try {
        const decodedSettings = Value.Decode(pluginSettingsSchema, settings);
        const decodedEnv = Value.Decode(envSchema, rawEnv || {});
        return { decodedEnv, decodedSettings };
    }
    catch (e) {
        if (e instanceof TransformDecodeCheckError || e instanceof TransformDecodeError) {
            throw { errors: [e.error] };
        }
        throw e;
    }
}
